    $processId = [int]$listener.OwningProcess
    $proc = Get-CimInstance Win32_Process -Filter "ProcessId = $processId"
    $cmd = [string]$proc.CommandLine
    $isAlpha = ($cmd -like "*$ROOT*") -and (
        ($cmd -like "*run_data_recovery_server.py*") -or
        ($cmd -like "*run_alpha_engine_v4.py*") -or
        ($cmd -like "*START_ALPHA_ENGINE*")
